package com.smartproperty.platform.parking.controller;
import com.smartproperty.platform.common.api.PageResult;import com.smartproperty.platform.parking.dto.ReviewParkingPermitApplicationRequest;import com.smartproperty.platform.parking.query.ParkingPermitQuery;import com.smartproperty.platform.parking.service.ParkingPermitService;import com.smartproperty.platform.parking.vo.*;import jakarta.validation.Valid;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/admin/parking-permits") public class ParkingPermitAdminController {private final ParkingPermitService service;public ParkingPermitAdminController(ParkingPermitService s){service=s;}@GetMapping("/summary")public ParkingPermitSummaryVO summary(){return service.adminSummary();}@GetMapping("/applications")public PageResult<ParkingPermitApplicationVO> applications(ParkingPermitQuery q){return service.pageApplications(q);}@GetMapping public PageResult<ParkingPermitVO> permits(ParkingPermitQuery q){return service.pagePermits(q);}@PatchMapping("/applications/{applicationId}/review")public ParkingPermitApplicationVO review(@PathVariable Long applicationId,@Valid @RequestBody ReviewParkingPermitApplicationRequest r){return service.review(applicationId,r);}}
